import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;import com.project.system.service.FinanceService;
public class FinanceEvidenceIntegration{public static void main(String[]args)throws Exception{try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(FinanceIntegration.Config.class)){FinanceService f=c.getBean(FinanceService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);long id=db.queryForObject("select l.id from campus_finance_line l join campus_finance_batch b on b.id=l.batch_id where b.status='OPEN' and l.handling_status='PENDING' and l.difference_code<>'MATCH' order by l.id desc limit 1",Long.class);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB),"png",out);String evidence=f.evidence(new FinanceIntegration.FileData("evidence.png",out.toByteArray()),1231);if(!"image/png".equals(f.file(evidence).get("mime")))throw new AssertionError();System.out.println("PASS valid evidence image saved and retrieved");f.handle(id,"测试凭证核实",evidence,1231);f.handle(id,"补充说明，保留原凭证",null,1231);if(!evidence.equals(db.queryForObject("select evidence_id from campus_finance_line where id=?",String.class,id)))throw new AssertionError();System.out.println("PASS resubmission preserves original evidence");try{f.handle(id,"错误使用其他人凭证",evidence,9999);throw new AssertionError();}catch(IllegalArgumentException expected){System.out.println("PASS cannot attach another operator evidence");}try{f.evidence(new FinanceIntegration.FileData("bad.png",new byte[]{1,2,3}),1231);throw new AssertionError();}catch(IllegalArgumentException expected){System.out.println("PASS invalid image rejected");}}}
}
